def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    r, c = next((i, j) for i in range(h) for j in range(w) if grid[i][j] == 3)

    # Spiral legs point up, right, down, left. Each pair of legs is
    # two cells longer than the previous pair.
    directions = [(-1, 0), (0, 1), (1, 0), (0, -1)]
    length = 2
    d = 0
    while True:
        for _ in range(2):
            dr, dc = directions[d % 4]
            for _ in range(length):
                r += dr
                c += dc
                if 0 <= r < h and 0 <= c < w:
                    if grid[r][c] != 2:
                        out[r][c] = 3
            d += 1
        length += 2
        if r < -h or r > 2 * h or c < -w or c > 2 * w:
            break
    return out
